        /// <summary>
        /// Zero-alloc CGNE (Conjugate Gradient on the Normal Equations, second kind; Saad,
        /// "Iterative Methods for Sparse Linear Systems," Algorithm 8.5 -- CGNE / Craig's method)
        /// solver for UNDERDETERMINED consistent systems A x = b (A Rows &lt;= Cols), generic over
        /// <see cref="IdoubleLinearOperator"/>. Solves A Aᵀ y = b by CG and forms x = Aᵀ y
        /// implicitly, MATRIX-FREE: A Aᵀ is never assembled -- each iteration costs exactly one
        /// A.Apply and one A.ApplyT. Requires A to have full row rank and b ∈ range(A) (a
        /// consistent system) -- on a square nonsingular A it recovers the unique solution.
        ///
        /// Every search direction p_k is built as an Aᵀ-image (p_0 = Aᵀr_0, p_{k+1} = Aᵀr_{k+1} +
        /// beta_k p_k), so x = Σ alpha_k p_k stays in row(A) at every iteration by construction --
        /// the same minimum-Euclidean-norm characterization x* = Aᵀ(AAᵀ)⁻¹b that
        /// <see cref="craig{TOp}"/> computes via Golub-Kahan bidiagonalization, here via a direct
        /// CG recurrence on the (never-formed) AAᵀ -- cheaper and simpler per step, at CG's usual
        /// κ² conditioning sensitivity. O(m+n) memory and per-iteration cost.
        ///
        /// No warm start (unlike lsqr/lsmr): the min-norm characterization only holds starting
        /// from x₀ = 0, so x is zeroed internally regardless of its incoming contents.
        ///
        /// Converges when ‖b-Ax‖ &lt;= tol*‖b‖. Returns an <see cref="LstsqInfo"/> -- see that
        /// struct for the implicit-bool/status/undefined-x contract; rnorm/Arnorm/xnorm are filled
        /// by a certified-exact <see cref="lstsqResidual{TOp}"/> audit (one extra Apply + ApplyT)
        /// rather than the tracked CG residual, since the recurrence's r can drift from the true
        /// ‖b-Ax‖ under accumulated rounding. A claimed Converged is reconciled against that
        /// certified rnorm (no extra matvec beyond the audit already paid for) before being
        /// reported -- falls through to another iteration if the tracked estimate turned out
        /// optimistic. Breakdown when p collapses (r numerically orthogonal to row(A)) before
        /// ‖b-Ax‖ reaches tolerance -- A lacks full row rank (or, on the very first step, b lies
        /// outside its row space).
        /// </summary>
        public static LstsqInfo cgne<TOp>(in TOp A, in doubleN b, ref doubleN x,
                                     ref doubleN r, ref doubleN p, ref doubleN Ap, ref doubleN tmpN,
                                     int maxIter, double tol)
            where TOp : struct, IdoubleLinearOperator
        {
            if (A.Rows > A.Cols) throw new ArgumentException("cgne: A must be square or underdetermined (Rows <= Cols)");
            if (b.N != A.Rows) throw new ArgumentException("cgne: b.N must equal A.Rows");
            if (x.N != A.Cols) throw new ArgumentException("cgne: x.N must equal A.Cols");
            if (r.N != A.Rows) throw new ArgumentException("cgne: r.N must equal A.Rows");
            if (p.N != A.Cols) throw new ArgumentException("cgne: p.N must equal A.Cols");
            if (Ap.N != A.Rows) throw new ArgumentException("cgne: Ap.N must equal A.Rows");
            if (tmpN.N != A.Cols) throw new ArgumentException("cgne: tmpN.N must equal A.Cols");

            if (maxIter < 1)
                throw new ArgumentException("cgne: maxIter must be >= 1");

            unsafe
            {
                long* ptrs = stackalloc long[6];
                ptrs[0] = (long)r.Data.Ptr; ptrs[1] = (long)p.Data.Ptr;
                ptrs[2] = (long)Ap.Data.Ptr; ptrs[3] = (long)tmpN.Data.Ptr;
                ptrs[4] = (long)x.Data.Ptr; ptrs[5] = (long)b.Data.Ptr;
                RequireDistinctBuffers("cgne: r/p/Ap/tmpN/x/b must be distinct", ptrs, 6);
            }

            // No warm start: the min-norm characterization x = Aᵀ(AAᵀ)⁻¹b requires x₀ = 0.
            for (int i = 0; i < x.N; i++) x[i] = (double)0;

            double bb = Blas.dot(b, b);
            if (bb == (double)0)
                // b = 0: the min-norm solution is trivially x = 0.
                return CGNEInfo(IterativeSolveStatus.Converged, 0, in A, in b, ref x, ref Ap, ref tmpN);

            // r_0 = b - A x_0 = b (x_0 = 0), so ‖r_0‖² == bb -- no extra dot needed.
            r.CopyFrom(in b);
            double rr = bb;

            double threshold = tol * tol * bb;
            if (rr <= threshold)
                return CGNEInfo(IterativeSolveStatus.Converged, 0, in A, in b, ref x, ref Ap, ref tmpN);

            // p_0 = Aᵀ r_0 -- an Aᵀ-image, so every later p_k (built below as Aᵀr_k + beta·p_{k-1})
            // stays in row(A) by induction, keeping x = Σ alpha_k p_k row(A)-minimal throughout.
            A.ApplyT(in r, ref p);

            for (int k = 0; k < maxIter; k++)
            {
                double pp = Blas.dot(p, p);
                if (!(pp > (double)0)) // NaN-safe: pp is a norm, nonnegative
                    // p collapsed before ‖r‖ reached tolerance: r is (numerically) orthogonal to
                    // row(A) -- A lacks full row rank (or b escaped range(A)). x is the previous
                    // iterate (undefined per the Breakdown contract).
                    return CGNEInfo(IterativeSolveStatus.Breakdown, k, in A, in b, ref x, ref Ap, ref tmpN);

                double alpha = rr / pp;

                // x += alpha p ; r -= alpha (A p) ; rr = ‖r‖², fused into one pass.
                A.Apply(in p, ref Ap);
                double rrNew = Blas.updateXR(alpha, p, ref x, Ap, ref r);

                if (rrNew <= threshold)
                {
                    // Verify-at-exit: the CG recurrence's tracked r can drift from the true
                    // residual over many iterations (accumulated rounding in the axpy chain).
                    // CGNEInfo already pays for a certified-exact ‖b-Ax‖ audit (lstsqResidual: one
                    // Apply + one ApplyT) for every exit regardless of status -- reuse THAT instead
                    // of a redundant matvec: only commit to Converged if the certified residual
                    // also clears the threshold. Ap/tmpN are safe to reuse either way (fully
                    // overwritten by the audit before their next read, so a fall-through loses
                    // nothing).
                    var info = CGNEInfo(IterativeSolveStatus.Converged, k + 1, in A, in b, ref x, ref Ap, ref tmpN);
                    if (info.rnorm * info.rnorm <= threshold)
                        return info;
                }

                // beta_k = ‖r_{k+1}‖² / ‖r_k‖² ; p_{k+1} = Aᵀ r_{k+1} + beta_k p_k.
                double beta = rrNew / rr;
                A.ApplyT(in r, ref tmpN);
                p.scaleAddInPlace(beta, tmpN);

                rr = rrNew;
            }

            return CGNEInfo(IterativeSolveStatus.MaxIterations, maxIter, in A, in b, ref x, ref Ap, ref tmpN);
        }

